{
  "items": [
    {
      "name": "BoxIntegral.Box.isBounded",
      "module_name": "Mathlib.Analysis.BoxIntegral.Box.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} [Finite ι] (I : BoxIntegral.Box ι), Bornology.IsBounded ↑I"
    },
    {
      "name": "BoxIntegral.le_hasIntegralVertices_of_isBounded",
      "module_name": "Mathlib.Analysis.BoxIntegral.UnitPartition",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} [Finite ι] {s : Set (ι → ℝ)}, Bornology.IsBounded s → ∃ B, BoxIntegral.hasIntegralVertices B ∧ s ≤ ↑B"
    },
    {
      "name": "BoxIntegral.Box.isBounded_Icc",
      "module_name": "Mathlib.Analysis.BoxIntegral.Box.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} [Finite ι] (I : BoxIntegral.Box ι), Bornology.IsBounded (BoxIntegral.Box.Icc I)"
    },
    {
      "name": "Behrend.mem_box",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {n d : ℕ} {x : Fin n → ℕ}, x ∈ Behrend.box n d ↔ ∀ (i : Fin n), x i < d"
    },
    {
      "name": "Finsupp.finite_of_degree_le",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} [Finite σ] (n : ℕ), {f | Finsupp.degree f ≤ n}.Finite"
    }
  ]
}
